# ruff: noqa: E501
"""Self-contained local UI. No external assets; untrusted strings use textContent."""

from __future__ import annotations

import html
import json

_PAGE = r"""<!doctype html>
<html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>SorbFlow · laboratorio local</title>
<style nonce="__NONCE__">
:root{font-family:system-ui,-apple-system,Segoe UI,sans-serif;color:#1b3042;background:#f2f6fa;font-synthesis:none}*{box-sizing:border-box}body{margin:0}header,main{max-width:1280px;margin:auto;padding:24px}header{display:flex;align-items:center;justify-content:space-between;gap:20px}h1{margin:0;font-size:30px;letter-spacing:-1px}h2{font-size:18px;margin:0 0 18px}p{line-height:1.5}.sub{color:#5a6c7b;font-size:14px;margin:6px 0}.badge{font-size:12px;border:1px solid #ce9839;background:#fff8df;color:#795614;border-radius:20px;padding:7px 12px;white-space:nowrap}main{padding-top:0}.notice{background:#e7eff8;border-left:4px solid #2e648e;border-radius:8px;padding:12px 16px;margin-bottom:20px;font-size:14px}.grid{display:grid;grid-template-columns:minmax(320px,1fr) minmax(320px,1.1fr);gap:20px}.card{background:#fff;border:1px solid #dbe4ec;border-radius:14px;padding:22px;box-shadow:0 3px 12px #193e5e06}label{display:block;font-size:13px;font-weight:600;margin-bottom:7px}select,input,textarea,button{font:inherit}select,input{width:100%;padding:9px;border:1px solid #bccbd8;border-radius:7px;background:white;color:#243b4c}textarea{width:100%;min-height:310px;padding:12px;border:1px solid #bccbd8;border-radius:8px;font:12px/1.5 ui-monospace,Consolas,monospace;resize:vertical;tab-size:2;color:#16344b;background:#fbfdff}select:focus,input:focus,textarea:focus{outline:2px solid #8cbadd;outline-offset:1px}.row{display:flex;gap:10px;align-items:end}.row>*{flex:1}.controls{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:14px 0}button{border:0;border-radius:8px;padding:11px 16px;background:#205d8d;color:#fff;cursor:pointer;font-weight:600}.secondary{color:#205d8d;background:#e8f0f7}.smallbutton{font-size:12px;padding:8px 11px}button:disabled{opacity:.5;cursor:wait}.help{font-size:12px;color:#607586;margin:9px 0 14px}#status{min-height:42px;padding:12px;background:#f3f7fa;border-radius:8px;margin-bottom:16px;white-space:pre-wrap}.error{color:#993f2e}.metrics{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:15px 0}.metric{border:1px solid #dde7ef;border-radius:9px;padding:12px}.metric strong{display:block;font-size:20px;overflow-wrap:anywhere}.metric span{font-size:12px;color:#607586}canvas{width:100%;height:290px;display:block;border:1px solid #e4ebf2;border-radius:9px}#downloads{display:flex;flex-wrap:wrap;gap:8px;margin-top:14px}#history{margin-top:20px}.historyitem{display:flex;justify-content:space-between;align-items:center;gap:10px;border-top:1px solid #e4ebf2;padding:10px 0;font-size:12px}.muted{font-size:12px;color:#6a7e8d}footer{font-size:12px;color:#617685;margin:20px 0 0}.hidden{display:none}@media(max-width:850px){.grid{grid-template-columns:1fr}header{align-items:flex-start;flex-direction:column}.controls{grid-template-columns:1fr 1fr}canvas{height:250px}}
</style></head><body>
<header><div><h1>SorbFlow</h1><p class="sub">Laboratorio local de adsorción acuosa · API científica 0.3</p></div><span class="badge">Resultados trazables</span></header>
<main><div class="notice">Simulación exploratoria con el motor Python propio. Los ejemplos son sintéticos; no representan un material calibrado ni un diseño certificado.</div>
<div class="grid"><section class="card"><h2>1. Configurar el ensayo</h2><div class="row"><div><label for="example">Ejemplo sintético</label><select id="example"></select></div><button id="load" class="secondary">Cargar</button></div>
<p class="help">La configuración JSON usa unidades SI según el nombre de cada campo. Concentración: kg/m³; carga: kg/kg seco; tiempo: s. 1 mg/L = 0,001 kg/m³. No se infieren unidades.</p>
<label for="config">Configuración física</label><textarea id="config" spellcheck="false" aria-label="Configuración JSON en unidades SI"></textarea>
<div class="controls"><div><label for="method">Integrador</label><select id="method"><option>BDF</option><option>Radau</option></select></div><div><label for="cells">Celdas axiales</label><input id="cells" type="number" min="2" max="64" value="40"></div><div><label for="radial">Celdas radiales</label><input id="radial" type="number" min="2" max="12" value="8"></div><div><label for="samples">Salidas</label><input id="samples" type="number" min="2" max="401" value="201"></div></div>
<div class="row"><button id="validate" class="secondary">Validar configuración</button><button id="run">Simular</button></div><p class="help">Una simulación a la vez. Límite local de ejecución: <span id="timeout">30</span> s. La malla de salida no fija los pasos internos. HSDM puede requerir una malla mayor mediante la API/CLI.</p></section>
<section class="card"><h2>2. Examinar resultados</h2><div id="status" role="status" aria-live="polite">Cargando ejemplos…</div><canvas id="plot" aria-label="Concentración de salida frente al tiempo"></canvas><div class="metrics"><div class="metric"><strong id="last">—</strong><span>Concentración final · kg/m³</span></div><div class="metric"><strong id="mass">—</strong><span>Máximo residuo de masa · kg</span></div></div><div class="muted" id="detail">Los controles numéricos no equivalen a validación física.</div><div id="downloads"></div><div id="history"><h2>Trabajos de esta sesión</h2><div id="jobs" class="muted">Sin simulaciones.</div></div></section></div>
<footer>Salida aislada por identificador, sin sobrescritura. No se ejecuta FAST ni se modifican datasets. Este servidor está limitado al equipo local.</footer></main>
<script nonce="__NONCE__">
'use strict';
const TOKEN=__TOKEN__;let examples=[],reactor='batch',active=null,timer=null;
const el=id=>document.getElementById(id);const headers={'X-SorbFlow-Token':TOKEN};
function status(text,error=false){el('status').textContent=text;el('status').className=error?'error':'';}
async function api(path,body){const r=await fetch(path,{method:body===undefined?'GET':'POST',headers:body===undefined?headers:{...headers,'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body),credentials:'same-origin'});const data=await r.json();if(!r.ok)throw new Error(data.error||'No se pudo completar la solicitud');return data;}
function payload(){return {reactor,config_json:el('config').value,options:{method:el('method').value,axial_cells:Number(el('cells').value),radial_cells:Number(el('radial').value)},samples:Number(el('samples').value)};}
function load(){const selected=examples.find(x=>x.id===el('example').value);if(!selected)return;reactor=selected.reactor;el('config').value=JSON.stringify(JSON.parse(selected.config_json),null,2);el('cells').value=reactor==='batch'?'40':'24';el('radial').value='8';status('Ejemplo sintético cargado. Revise parámetros y unidades antes de simular.');}
function plot(preview){const canvas=el('plot'),ctx=canvas.getContext('2d'),ratio=window.devicePixelRatio||1;canvas.width=Math.round(canvas.clientWidth*ratio);canvas.height=Math.round(canvas.clientHeight*ratio);ctx.scale(ratio,ratio);const w=canvas.clientWidth,h=canvas.clientHeight,l=65,r=18,t=24,b=45;ctx.clearRect(0,0,w,h);ctx.fillStyle='#607586';ctx.font='11px system-ui';if(!preview){ctx.fillText('La curva aparecerá tras una simulación completa.',22,40);return;}const x=preview.time_s.map(v=>v/60),y=preview.outlet_concentration_kg_m3;const xmax=Math.max(...x,1e-12),ymax=Math.max(...y,1e-12)*1.08;ctx.strokeStyle='#e1e9f0';ctx.lineWidth=1;for(let i=0;i<=4;i++){const yy=t+(h-t-b)*i/4;ctx.beginPath();ctx.moveTo(l,yy);ctx.lineTo(w-r,yy);ctx.stroke();ctx.fillText((ymax*(1-i/4)).toExponential(1),3,yy+4);const xx=l+(w-l-r)*i/4;ctx.fillText((xmax*i/4).toFixed(1),xx-8,h-24);}ctx.fillText('Salida · kg/m³',l,t-9);ctx.fillText('Tiempo · min',w/2-30,h-6);ctx.strokeStyle='#1f6b9d';ctx.lineWidth=2.4;ctx.beginPath();x.forEach((v,i)=>{const xx=l+(w-l-r)*v/xmax,yy=t+(h-t-b)*(1-y[i]/ymax);i?ctx.lineTo(xx,yy):ctx.moveTo(xx,yy);});ctx.stroke();}
async function download(id,name){try{const r=await fetch('/api/jobs/'+id+'/files/'+name,{headers,credentials:'same-origin'});if(!r.ok){const err=await r.json();throw new Error(err.error);}const url=URL.createObjectURL(await r.blob()),a=document.createElement('a');a.href=url;a.download=id+'_'+name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){status(e.message,true);}}
function files(job){el('downloads').replaceChildren();const names=job.status==='succeeded'?['result.json','timeseries.csv','summary.json','job.log']:['summary.json','job.log'];names.forEach(name=>{const button=document.createElement('button');button.className='secondary smallbutton';button.textContent=name;button.addEventListener('click',()=>download(job.id,name));el('downloads').appendChild(button);});}
async function refresh(){try{const data=await api('/api/jobs');el('jobs').replaceChildren();if(!data.jobs.length){el('jobs').textContent='Sin simulaciones.';return;}data.jobs.forEach(job=>{const row=document.createElement('div');row.className='historyitem';const label=document.createElement('span');label.textContent=job.reactor+' · '+job.id.slice(0,10)+' · '+job.status;const button=document.createElement('button');button.className='secondary smallbutton';button.textContent='Ver';button.addEventListener('click',()=>poll(job.id));row.append(label,button);el('jobs').appendChild(row);});}catch(e){status(e.message,true);}}
async function poll(id){try{const job=await api('/api/jobs/'+id);if(job.status==='queued'||job.status==='running'){status('Simulación '+job.status+' · '+job.id.slice(0,10));clearTimeout(timer);timer=setTimeout(()=>poll(id),600);return;}active=null;el('run').disabled=false;files(job);if(job.status==='succeeded'){status('Simulación completada. Revisar balance, malla y supuestos antes de interpretar.');plot(job.preview);const y=job.preview.outlet_concentration_kg_m3;el('last').textContent=y[y.length-1].toExponential(3);el('mass').textContent=job.diagnostics.max_abs_mass_residual_kg.toExponential(3);el('detail').textContent='Residuo escalado máximo: '+job.diagnostics.max_scaled_mass_residual.toExponential(3)+'. Sin validación experimental.';}else{status((job.status==='timed_out'?'Tiempo local agotado. ':'La simulación no produjo un resultado exitoso. ')+(job.error||'Consultar el registro.'),true);}await refresh();}catch(e){active=null;el('run').disabled=false;status(e.message,true);}}
el('load').addEventListener('click',load);el('validate').addEventListener('click',async()=>{try{const data=await api('/api/validate',payload());status('Configuración y límites locales correctos. No valida la física ni los parámetros.\nSHA-256: '+data.config_sha256);}catch(e){status(e.message,true);}});
el('run').addEventListener('click',async()=>{el('run').disabled=true;try{const job=await api('/api/jobs',payload());active=job.id;await refresh();await poll(job.id);}catch(e){el('run').disabled=false;status(e.message,true);}});
async function init(){try{const info=await api('/api/info');el('timeout').textContent=String(info.job_timeout_s);const data=await api('/api/examples');examples=data.examples;examples.forEach(example=>{const option=document.createElement('option');option.value=example.id;option.textContent=example.label;el('example').appendChild(option);});plot(null);load();await refresh();}catch(e){status(e.message,true);}}
init();
</script></body></html>"""


def page(token: str, nonce: str) -> bytes:
    """Token is a generated secret, never caller-provided HTML or configuration text."""
    return (
        _PAGE.replace("__NONCE__", html.escape(nonce, quote=True))
        .replace("__TOKEN__", json.dumps(token))
        .encode("utf-8")
    )
